<?php
require_once __DIR__.'/../ajax/borrower.php';
$borrower=borrower_user();
$installments=db("SELECT i.*,a.agreement_id FROM loan_installments i JOIN loan_agreements a ON a.agreement_id=i.agreement_id WHERE a.borrower_id=? AND a.status='active' AND i.amount_paid<i.amount_due ORDER BY i.due_date",[$borrower['user_id']])->get_result()->fetch_all(MYSQLI_ASSOC);
$requests=db('SELECT * FROM extension_requests WHERE borrower_id=? ORDER BY requested_at DESC',[$borrower['user_id']])->get_result()->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Extension | Utang Wise</title><link rel="stylesheet" href="../assets/css/payment-extension.css"><link rel="stylesheet" href="../assets/css/lender-flow.css"></head><body><main class="uw-borrower-box"><a href="client-dashboard.php">Back to dashboard</a><h1>Payment Extension</h1><p>Request a later due date. Your lender will review the request before the schedule changes.</p><?php notice(); ?>
<?php if($installments): ?><form class="uw-form" method="post" action="../controllers/borrower-extension.php"><?php csrf(); ?><label>Unpaid installment<select name="installment_id" required><option value="">Choose an installment</option><?php foreach($installments as $i): ?><option value="<?= (int)$i['installment_id'] ?>">Loan UW-<?= (int)$i['agreement_id'] ?> · Installment <?= (int)$i['installment_number'] ?> · Due <?= e($i['due_date']) ?> · PHP <?= e(number_format((float)$i['amount_due']-(float)$i['amount_paid'],2)) ?></option><?php endforeach; ?></select></label><label>Requested due date<input type="date" name="requested_due_date" min="<?= date('Y-m-d') ?>" required></label><label>Reason<textarea name="reason" minlength="5" maxlength="2000" required></textarea></label><p>If approved, this and subsequent unpaid installments move by the same number of days. No extra interest or fees are added.</p><button class="uw-button" type="submit">Submit request</button></form><?php else: ?><p>You have no unpaid installments on an active loan.</p><?php endif; ?>
<h2>Your requests</h2><?php foreach($requests as $r): ?><section class="uw-profile-section"><strong>EXT-<?= (int)$r['request_id'] ?> · <?= e(ucfirst($r['status'])) ?></strong><p><?= e($r['original_due_date'].' → '.$r['requested_due_date']) ?></p><p><?= e($r['review_reason']?:$r['reason']) ?></p></section><?php endforeach; ?><?php borrower_logout_button(); ?></main><?php if(function_exists('uw_success_assets'))uw_success_assets(); ?></body></html>
